import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.nkraVhM_.js";var i=JSON.parse(`{"title":"Usage Guide","description":"","frontmatter":{},"headers":[],"relativePath":"guide/usage.md","filePath":"guide/usage.md","lastUpdated":1785319710000}`),a={name:`guide/usage.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="usage-guide" tabindex="-1">Usage Guide <a class="header-anchor" href="#usage-guide" aria-label="Permalink to “Usage Guide”">​</a></h1><h2 id="basic-gameplay" tabindex="-1">Basic Gameplay <a class="header-anchor" href="#basic-gameplay" aria-label="Permalink to “Basic Gameplay”">​</a></h2><h3 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to “Objective”">​</a></h3><p>Fill a 9×9 grid so that every <strong>row</strong>, every <strong>column</strong>, and each of the nine 3×3 <strong>boxes</strong> contains all digits from 1 to 9 exactly once. No repetition allowed in any unit.</p><h3 id="how-to-play" tabindex="-1">How to Play <a class="header-anchor" href="#how-to-play" aria-label="Permalink to “How to Play”">​</a></h3><ul><li><strong>Place a number</strong>: Tap or click an empty cell, then tap a digit from the number pad at the bottom of the screen.</li><li><strong>Pencil notes (candidates)</strong>: Toggle Pencil mode, then tap cells to write small candidate digits. Useful for tracking possibilities.</li><li><strong>Erase</strong>: Tap the Erase button to clear a cell&#39;s value (or pencil marks when in pencil mode).</li><li><strong>Hint</strong>: Tap Hint to reveal one correct cell&#39;s value.</li><li><strong>Undo</strong>: Tap Undo to reverse your last move (supports full undo history).</li></ul><h3 id="difficulty-levels" tabindex="-1">Difficulty Levels <a class="header-anchor" href="#difficulty-levels" aria-label="Permalink to “Difficulty Levels”">​</a></h3><p>Each difficulty level determines how many cells are pre-filled (given) at the start:</p><table tabindex="0"><thead><tr><th>Level</th><th>Given Cells</th><th>Best For</th></tr></thead><tbody><tr><td>Easy</td><td>45</td><td>Beginners &amp; quick games</td></tr><tr><td>Medium</td><td>36</td><td>Casual players</td></tr><tr><td>Hard</td><td>31</td><td>Regular solvers</td></tr><tr><td>Expert</td><td>27</td><td>Experienced players</td></tr><tr><td>Master</td><td>24</td><td>Puzzle masters</td></tr></tbody></table><p><img src="/screenshot-mac-main.png" alt="Sudoku game board on Mac"></p><h2 id="game-controls" tabindex="-1">Game Controls <a class="header-anchor" href="#game-controls" aria-label="Permalink to “Game Controls”">​</a></h2><h3 id="iphone-ipad" tabindex="-1">iPhone / iPad <a class="header-anchor" href="#iphone-ipad" aria-label="Permalink to “iPhone / iPad”">​</a></h3><ul><li><strong>Tap</strong> an empty cell to select it</li><li><strong>Tap a number</strong> on the keypad to place it</li><li><strong>Toggle Pencil mode</strong> to enter/erase candidate notes</li><li><strong>Use Erase</strong> to clear a cell</li><li><strong>Use Hint</strong> for help when stuck</li><li><strong>Use Undo</strong> to take back moves</li></ul><h3 id="mac" tabindex="-1">Mac <a class="header-anchor" href="#mac" aria-label="Permalink to “Mac”">​</a></h3><ul><li><strong>Left-click</strong> an empty cell to select it</li><li><strong>Type a number key (1–9)</strong> or click the on-screen keypad to place</li><li><strong>Toggle Pencil mode</strong> for candidate notes</li><li><strong>Keyboard shortcuts</strong>: <ul><li><code>⌘N</code> — New game</li><li><code>⌘Z</code> — Undo</li><li><code>⌘1</code> through <code>⌘5</code> — Start new game at each difficulty level</li></ul></li></ul><p><img src="/screenshot-iphone-main.png" alt="Sudoku home screen on iPhone"></p><p><img src="/screenshot-ipad-main.png" alt="Sudoku home screen on iPad"></p><h2 id="smart-features" tabindex="-1">Smart Features <a class="header-anchor" href="#smart-features" aria-label="Permalink to “Smart Features”">​</a></h2><h3 id="pencil-notes-system" tabindex="-1">Pencil Notes System <a class="header-anchor" href="#pencil-notes-system" aria-label="Permalink to “Pencil Notes System”">​</a></h3><p>When you enable Pencil mode, you can write small candidate digits in empty cells. The smart pencil system:</p><ul><li><strong>Auto-clears peer pencil marks</strong>: When you place a definitive number, pencil marks for that digit are automatically removed from all cells in the same row, column, and box.</li><li><strong>Toggle per cell</strong>: Switch between entry mode and pencil mode at any time.</li></ul><h3 id="error-checking" tabindex="-1">Error Checking <a class="header-anchor" href="#error-checking" aria-label="Permalink to “Error Checking”">​</a></h3><p>Optional error highlighting shows incorrect entries in red, helping you learn without spoiling the puzzle.</p><h3 id="daily-challenge" tabindex="-1">Daily Challenge <a class="header-anchor" href="#daily-challenge" aria-label="Permalink to “Daily Challenge”">​</a></h3><p>A fresh Master-level puzzle is generated every day. Your daily challenge progress is tracked in Statistics with a calendar view showing your streak.</p><h3 id="statistics" tabindex="-1">Statistics <a class="header-anchor" href="#statistics" aria-label="Permalink to “Statistics”">​</a></h3><p>Track your Sudoku journey:</p><ul><li>Total games played and win rate</li><li>Current streak and best streak</li><li>Per-difficulty breakdown: games won, best time, average time</li><li>Daily Challenge calendar with completion indicators</li></ul><p><img src="/screenshot-mac-settings.png" alt="Sudoku statistics on Mac"></p><h2 id="themes" tabindex="-1">Themes <a class="header-anchor" href="#themes" aria-label="Permalink to “Themes”">​</a></h2><p>Choose from eight beautiful color themes in Settings:</p><table tabindex="0"><thead><tr><th>Theme</th><th>Style</th></tr></thead><tbody><tr><td>Classic</td><td>Clean white with blue accents</td></tr><tr><td>Midnight</td><td>Dark mode with deep blues</td></tr><tr><td>Paper</td><td>Warm parchment texture</td></tr><tr><td>Forest</td><td>Natural greens</td></tr><tr><td>Ocean</td><td>Calm sea blues</td></tr><tr><td>Sunset</td><td>Warm orange gradients</td></tr><tr><td>Lavender</td><td>Soft purple tones</td></tr><tr><td>Rose</td><td>Elegant pink palette</td></tr></tbody></table><h2 id="icloud-sync" tabindex="-1">iCloud Sync <a class="header-anchor" href="#icloud-sync" aria-label="Permalink to “iCloud Sync”">​</a></h2><p>When signed into iCloud on your device:</p><ul><li>Game saves sync automatically — continue on any device</li><li>Statistics and settings stay in sync</li><li>Daily Challenge progress transfers across devices</li><li>Requires iOS/iPadOS 16+ or macOS 15+</li></ul><h2 id="game-center" tabindex="-1">Game Center <a class="header-anchor" href="#game-center" aria-label="Permalink to “Game Center”">​</a></h2><p>Connect with Game Center to:</p><ul><li>Compete on <strong>leaderboards</strong> for best completion times per difficulty</li><li>Earn <strong>achievements</strong>: First Solve, Easy/Medium/Hard/Expert/Master Clear, Flawless (no hints or errors)</li></ul><h2 id="print-puzzles-mac" tabindex="-1">Print Puzzles (Mac) <a class="header-anchor" href="#print-puzzles-mac" aria-label="Permalink to “Print Puzzles (Mac)”">​</a></h2><p>On Mac, print puzzles directly from the app:</p><ol><li>Open the <strong>Print</strong> dialog from the toolbar</li><li>Select difficulty level (Easy through Master)</li><li>Toggle &quot;Include Answers&quot; if desired</li><li>Click <strong>Print</strong></li></ol><p>Perfect for solving offline with pen and paper!</p><h2 id="sound-effects" tabindex="-1">Sound Effects <a class="header-anchor" href="#sound-effects" aria-label="Permalink to “Sound Effects”">​</a></h2><p>Sudoku includes subtle sound effects:</p><ul><li>Number placement confirmation</li><li>Hint revealed</li><li>Error alert</li><li>Victory celebration</li></ul><p>Toggle sound on or off in <strong>Settings → Sound</strong>.</p><h2 id="tips-and-tricks" tabindex="-1">Tips and Tricks <a class="header-anchor" href="#tips-and-tricks" aria-label="Permalink to “Tips and Tricks”">​</a></h2><ul><li><strong>Start with what&#39;s given</strong> — scan rows, columns, and boxes that already have many numbers filled.</li><li><strong>Use pencil notes</strong> — they&#39;re especially helpful on Hard, Expert, and Master difficulties.</li><li><strong>Look for naked singles</strong> — if a cell has only one possible candidate, fill it in.</li><li><strong>Look for hidden singles</strong> — if a digit can only go in one place within a row/column/box, place it there.</li><li><strong>Use hints sparingly</strong> — they&#39;re great for learning, but completing a puzzle without hints feels more rewarding.</li><li><strong>Build your daily streak</strong> — the Daily Challenge is a great way to practice consistently.</li></ul>`,48)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};